calls.query:
/bin/bash -lc "set -euo pipefail
node - <<'NODE'
const fs=require('fs'); const o=JSON.parse(fs.readFileSync('/tmp/hookdeck-openapi.json','utf8'));
console.log(JSON.stringify({servers:o.servers, paths:Object.fromEntries(Object.entries(o.paths).filter(([k])=>k.includes('issue-trigger')||k.includes('notification'))) }, null, 2));
NODE
printf '%s\\n' '--- current issue triggers ---'
curl -fsSL https://api.hookdeck.com/2025-07-01/issue-triggers -H \"Authorization: Bearer "'$HOOKDECK_API_KEY" | tee /tmp/issue-triggers.json
printf '"'\\n%s\\n' '--- relevant schema names ---'
node - <<'NODE'
const fs=require('fs'); const o=JSON.parse(fs.readFileSync('/tmp/hookdeck-openapi.json','utf8'));
for (const [name,schema] of Object.entries(o.components?.schemas||{})) {
  if (/IssueTrigger|Notification|Channel/i.test(name)) console.log('\\n### '+name+'\\n'+JSON.stringify(schema,null,2));
}
NODE
printf '%s\\n' '--- issue notification product docs ---'
curl -fsSL https://hookdeck.com/docs/issues.md | sed -n '1,260p'
"
